public class TileMapGenerator2 : MonoBehaviour
{
    [SerializeField] Tilemap tilemap;
    [SerializeField] TileBase waterTile;
    [SerializeField] TileBase groundTile;
    [SerializeField] TileBase featureTile; // trees
    [SerializeField] int width = 100, height = 128;
    [SerializeField] float scale = 25f;
    [SerializeField] int seed = 6197;

    void Start() => Generate();

    [ContextMenu("Generate")]
    public void Generate()
    {
        tilemap.ClearAllTiles();
        var offset = new Vector2(seed * 13.37f, seed * 7.77f);
        for (int x = 0; x < width; x++)
        for (int y = 0; y < height; y++)
        {
            float n = Mathf.PerlinNoise(x / scale + offset.x, y / scale + offset.y);
            TileBase tile = n < 0.3f ? waterTile : n > 0.7f ? featureTile : groundTile;
            tilemap.SetTile(new Vector3Int(x - width / 2, y - height / 2, 0), tile);
        }
    }
}
